from __future__ import annotations

import os
import tempfile
import unittest
from pathlib import Path
from unittest import mock

from github_fix.core import hosts


SAMPLE = """# Windows hosts
127.0.0.1 localhost
# === GitHub Fix START ===
# generated by old script
1.2.3.4 github.com
# === GitHub Fix END ===
10.0.0.1 my.internal
# >>> GitHubFix managed block >>>
5.6.7.8 github.com
# <<< GitHubFix managed block <<<
"""


class HostsTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.root = Path(self.tmp.name)
        self.path = self.root / "hosts"
        self.path.write_text(SAMPLE, encoding="utf-8")
        self.data_env = mock.patch.dict(os.environ, {"GITHUBFIX_DATA_DIR": str(self.root / "data")})
        self.data_env.start()
        self.admin_env = mock.patch.object(hosts, "is_admin", return_value=True)
        self.admin_env.start()

    def tearDown(self):
        self.admin_env.stop()
        self.data_env.stop()
        self.tmp.cleanup()

    def test_strip_removes_managed_and_legacy_blocks_only(self):
        cleaned, ours, legacy = hosts.strip_managed_blocks(SAMPLE)
        self.assertEqual(ours, 1)
        self.assertEqual(legacy, 1)
        self.assertIn("127.0.0.1 localhost", cleaned)
        self.assertIn("10.0.0.1 my.internal", cleaned)
        self.assertNotIn("1.2.3.4 github.com", cleaned)
        self.assertNotIn("5.6.7.8 github.com", cleaned)

    def test_apply_and_restore_preserve_user_lines(self):
        _, backup, legacy = hosts.apply_hosts({"github.com": "9.9.9.9"}, self.path, flush=False)
        self.assertEqual(legacy, 1)
        self.assertTrue(backup and Path(backup).exists())
        snapshot = hosts.read_hosts(self.path)
        self.assertEqual(snapshot.managed_count, 1)
        self.assertEqual(snapshot.legacy_count, 0)
        self.assertEqual(snapshot.entries["github.com"], ["9.9.9.9"])
        self.assertIn("my.internal", snapshot.text)

        _, _, removed = hosts.restore_hosts(self.path, flush=False)
        self.assertEqual(removed, 1)
        text = self.path.read_text(encoding="utf-8")
        self.assertIn("127.0.0.1 localhost", text)
        self.assertIn("my.internal", text)
        self.assertNotIn("9.9.9.9", text)
        self.assertNotIn("GitHubFix managed", text)

    def test_invalid_entries_are_rejected(self):
        with self.assertRaises(ValueError):
            hosts.apply_hosts({"bad host": "1.1.1.1"}, self.path, flush=False)
        with self.assertRaises(ValueError):
            hosts.apply_hosts({"github.com": "127.0.0.1"}, self.path, flush=False)

    def test_build_block_contains_valid_entries(self):
        block = hosts.build_block({"github.com": "9.9.9.9", "raw.githubusercontent.com": "8.8.8.8"})
        self.assertIn("9.9.9.9\tgithub.com", block)
        self.assertIn(hosts.OUR_START, block)
        self.assertIn(hosts.OUR_END, block)

    def test_unbalanced_block_is_preserved(self):
        text = "# user\n" + hosts.OUR_START + "\n1.1.1.1 github.com\n10.0.0.1 keep.me\n"
        cleaned, ours, legacy = hosts.strip_managed_blocks(text)
        self.assertEqual((ours, legacy), (0, 0))
        self.assertIn("keep.me", cleaned)
        self.assertIn(hosts.OUR_START, cleaned)

    def test_decode_bom(self):
        text, encoding = hosts.decode_hosts(b"\xef\xbb\xbf# test\r\n")
        self.assertEqual(encoding, "utf-8-sig")
        self.assertEqual(text, "# test\r\n")
